{
  "sql": "SELECT p.product_name, (SUM(CASE WHEN EXTRACT(YEAR FROM r.return_date) = 2022 THEN r.return_quantity ELSE 0 END) * 1.0 / NULLIF(SUM(CASE WHEN EXTRACT(YEAR FROM oi.order_date) = 2022 THEN oi.quantity ELSE 0 END), 0)) AS return_ratio FROM commerce.products AS p JOIN commerce.order_items AS oi ON p.product_id = oi.product_id JOIN commerce.orders AS o ON oi.order_id = o.order_id LEFT JOIN commerce.returns AS r ON oi.order_id = r.order_id AND p.product_id = r.product_id WHERE o.order_date >= '2022-01-01' AND o.order_date < '2023-01-01' GROUP BY p.product_name ORDER BY 2 DESC LIMIT 200",
  "parameters": [],
  "explanation": "This query calculates the ratio of returned units to ordered units for each product in 2022. It joins products with order items and orders to get the ordered quantities. It left joins returns to capture returned quantities, filtering for returns in 2022. The ratio is calculated as the sum of returned quantities divided by the sum of ordered quantities. The results are ordered by this ratio in descending order to find the products with the highest return rates."
}

